import React from 'react';
import './Home.css';

const Home = () => {
  return (
    <div className="home">
      <div className="overlay">
        <h1>Centro de Educación - FREE TRADER</h1>
        <p>Explora nuestros cursos y empieza a aprender a programar ya.</p>
      </div>
    </div>
  );
};

export default Home;
